import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Takes a statement: the person's due-total as the screen shows it now (the sum of their counting
 * claims' dues — each fixed or at the rate in force on its date, its late charge on top, raised to the floor in force on its date;
 * n/a when their grade has no rate today and no claim keeps a figure; held to the sheet's cap), and binds each counting claim to
 * its rate figure now — never the floor or its late charge, which keep being applied live.
 * A claim that does not count (an unbound OPEN claim dated within one of its person's holds, or a deferred claim, included) is left unbound.
 * <p>
 * Taken as of a date (on or before the sheet's today, and not before the person was added), the same is worked from the
 * store as it stood at the end of that date (see {@link AsOf}), that date standing in for the sheet's today: the claims
 * that counted then are bound to their figures then, the person's other claims are left unbound, and the statement is
 * dated that date.
 */
public class TakeStatement {
    public void take(@Val StatementRequest request, @Val Person person, Claims claims, AsOf asOf, Sheets sheets,
            People people, Out<Statement> statement) throws InvalidPersonException {
        String sheetId = person.getSheetId();
        LocalDate date = asOfDate(request, person, sheets.today(sheetId));
        AsOf.View view = date == null ? asOf.now(person) : asOf.at(person, date);
        LocalDate today = view.today();
        Person then = view.person();
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean anyFigure = false;
        int counted = 0;
        // The figure each counting claim is bound to, by id (a null figure: n/a).
        Map<Long, BigDecimal> bound = new HashMap<>();
        for (Claim claim : view.claims()) {
            if (!then.countsLive(claim, today)) {
                continue;
            }
            RoundingMode rounding = Rounding.of(claim, view.policyDate());
            BigDecimal fixed = ClaimResponse.fixedDue(claim);
            // A bound claim keeps its figure (even n/a); a live one is worked at the rate on its date (unfloored).
            BigDecimal figure = fixed != null || claim.isBound() ? fixed
                    : Rates.due(claim.getAmount(), view.rate().apply(then.gradeOn(claim.getDate()), claim.getDate()), rounding);
            if (figure != null) {
                anyFigure = true;
                total = total.add(LateCharge.due(claim, figure, view.floor().apply(claim.getDate()), view.latePct(),
                        today, rounding));
            }
            bound.put(claim.getId(), figure);
            counted++;
        }
        for (Claim claim : date == null ? view.claims() : claims.ofPerson(sheetId, person.getId())) {
            claim.setStated(bound.containsKey(claim.getId()));
            claim.setStatedDue(bound.get(claim.getId()));
            claims.bind(claim);
        }
        // n/a only when no claim keeps or gets a figure (each at the grade in force on its date).
            claim.setNumber(numbering.next(claim.getSheetId(), claim.getPeriodDate()));
            claim.setOpenedBy(request.user());
        }
        // A voided claim keeps its number; numbers are never reused.
        ClaimNumber number = new ClaimNumber(claim.getNumber());
        if (target == ClaimStatus.SETTLED) {
            // Settling (or approving) fixes the due: the figure a statement bound it to (never while PENDING), else its amount
            // at the rate in force on the claim's date, with its late charge as of today on top and raised to the floor, frozen in;
            // with no figure it stays live (n/a until a rate is set).
            String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
            BigDecimal figure = claim.isBound() && claim.getStatedDue() != null ? claim.getStatedDue()
                    : Rates.due(claim.getAmount(), rates.find(claim.getSheetId(), grade, claim.getDate()), rounding);
            claim.setSettledDue(LateCharge.due(claim, figure, settings.floor(claim.getSheetId(), claim.getDate()),
                    on -> settings.latePct(claim.getSheetId(), on), sheets.today(claim.getSheetId()), rounding));
        }
        // A rejected claim is OPEN again, so bound again by the last statement if it included it.
        claim.setStatus(target);
        return number;
    }

    /** Refuses opening a claim with an empty note whose due as shown is above the note threshold in force on its date;
     *  a due of n/a is within any threshold. Bulk open uses it too. */
    static void refuseNoteless(Claim claim, Sheets sheets, People people, Rates rates, Settings settings,
            RoundingMode rounding) throws ClaimStatusRefusedException {
        if (claim.getNote() != null && !claim.getNote().trim().isEmpty()) {
            return;
        }
        BigDecimal threshold = settings.noteThreshold(claim.getSheetId(), claim.getDate());
        if (threshold == null) {
            return;
        }
        BigDecimal due = shownDue(claim, sheets, people, rates, settings, rounding);
        if (due != null && due.compareTo(threshold) > 0) {
            throw new ClaimStatusRefusedException("A claim whose due is above the note threshold needs a note to be opened");
        }
    }

    /** The claim's due as shown: fixed (settled or bound), else its live figure with its late charge as of today; null for n/a. */
    private static BigDecimal shownDue(Claim claim, Sheets sheets, People people, Rates rates, Settings settings,
            RoundingMode rounding) {
        String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
        BigDecimal fixed = ClaimResponse.fixedDue(claim);
        BigDecimal figure = fixed != null || claim.isBound() ? fixed
                : Rates.due(claim.getAmount(), rates.find(claim.getSheetId(), grade, claim.getDate()), rounding);
        return LateCharge.due(claim, figure, settings.floor(claim.getSheetId(), claim.getDate()),
                on -> settings.latePct(claim.getSheetId(), on), sheets.today(claim.getSheetId()), rounding);
    }
}
        close(sheetId, period, user, false, true);
    }

    private void close(String sheetId, PeriodResponse period, String user, boolean auto, boolean soft) {
        LocalDate from = LocalDate.parse(period.from());
        LocalDate to = LocalDate.parse(period.to());
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        LocalDate policyDate = settings.policyDate(sheetId);
        LocalDate today = sheets.today(sheetId);
        List<Claim> all = claims.list(sheetId);
        Map<Long, BigDecimal> personTotals = new LinkedHashMap<>();
        for (Person person : people.list(sheetId)) {
            BigDecimal personTotal = BigDecimal.ZERO.setScale(2);
            for (Claim claim : all) {
                if (claim.getPersonId() != person.getId() || !person.countsAtEnd(claim, to, today)
                        || claim.getPeriodDate().isBefore(from) || claim.getPeriodDate().isAfter(to)) {
                    continue;
                }
                RoundingMode rounding = Rounding.of(claim, policyDate);
                BigDecimal fixed = ClaimResponse.fixedDue(claim);
                BigDecimal figure = fixed != null || claim.isBound() ? fixed
                        : Rates.due(claim.getAmount(), rates.find(sheetId, person.gradeOn(claim.getDate()), claim.getDate()), rounding);
                if (figure != null) {
                    personTotal = personTotal.add(LateCharge.due(claim, figure, settings.floor(sheetId, claim.getDate()),
                            on -> settings.latePct(sheetId, on), today, rounding));
                }
            }
            personTotals.put(person.getId(), personTotal);
            total = total.add(personTotal);
        }
        periods.close(sheetId, period.name(), total, personTotals, soft);
            throw new ClaimStatusRefusedException("No claim whose due-by is inside a closed period can be re-settled");
        }
        RoundingMode rounding = Rounding.of(claim, settings.policyDate(sheetId));
        String grade = people.find(sheetId, claim.getPersonId()).gradeOn(claim.getDate());
        BigDecimal figure = Rates.due(claim.getAmount(), rates.find(sheetId, grade, claim.getDate()), rounding);
        BigDecimal due = figure == null ? null
                : LateCharge.floored(claim, figure.add(LateCharge.asOpen(claim, figure, on -> settings.latePct(sheetId, on),
                        sheets.today(sheetId), rounding)), settings.floor(sheetId, claim.getDate()));
        BigDecimal old = claim.getSettledDue();
        claim.setSettledDue(due);
        resettle.set(new ClaimResettle(old, due));

